// MIBTECH building geometry from the architect's plans (mibtechPlanData.ts, generated by docs/research/mibtech-plan-extract.py).
// Pure geometry, no React: merged BufferGeometries per material, in the BUILDING frame of the plans (metres; x along the
// street façade towards the north-east, z towards the street, origin = middle of the façade glass; y up from the pavement).
//
// Heights are NOT in the plans (« plan cotation » only): every one below is a documented provisional value.
//   · ground floor 4.6 m (street photos), floor to floor 3.8 m (chosen by the project owner, provisional; the stair drawn on
//     the plans — 18 treads of 28.2 cm — would rather suggest ≈ 3.5 m by Blondel's rule), slab 0.30 m, suspended ceiling
//     at 2.80 m, window sill 0.90 m / head 2.60 m, WC cubicles 2.10 m, doors 2.10 m.
import * as THREE from "three";
import { MIBTECH_PLANS, type FloorPlan, type PlanPoly } from "./mibtechPlanData";
import { FURN_KINDS, MIBTECH_FURNITURE, type FurnItem } from "./mibtechFurnitureData";

export const MB_H = {
  ground: 4.6, floor: 3.8, slab: 0.3, ceiling: 2.8, sill: 0.9, head: 2.6, cubicle: 2.1, door: 2.1,
} as const;
export const MB_FLOORS = [1, 2, 3] as const;
export type MbFloor = (typeof MB_FLOORS)[number];
/** level of the finished floor of each office floor (y) */
export const floorY = (f: MbFloor) => MB_H.ground + (f - 1) * MB_H.floor;
/** top of the roof slab */
export const MB_TOP = floorY(3) + MB_H.floor;

export type MbMat = "wall" | "column" | "partition" | "glass" | "frame" | "door" | "cubicle" | "floor" | "ceiling" | "slabEdge" | "lift" | "roof" | "groundWall" | "stair" | "rail"
  // interior finishes and furniture (lot 5: from the office photos and the architect's electrical plans)
  | "frost" | "terrace" | "desk" | "chair" | "metal" | "panel" | "screen" | "leaf" | "pot" | "fabric" | "porcelain" | "cabinet" | "carpet" | "walnut";
type Acc = { pos: number[]; nor: number[]; uv: number[]; idx: number[] };
const TILE: Record<MbMat, number> = {
  // wall, column, partition: one texture = 4 m, its v measured from the floor (the skirting at the bottom)
  wall: 4, column: 4, partition: 4, glass: 2, frame: 1, door: 2.2, cubicle: 2.2, floor: 1.2, ceiling: 2.4, slabEdge: 1, lift: 1, roof: 4, groundWall: 2.4, stair: 1, rail: 1,
  frost: 2.8, terrace: 1.2, desk: 1, chair: 1, metal: 1, panel: 1, screen: 1, leaf: 1, pot: 1, fabric: 1, porcelain: 1, cabinet: 1, carpet: 1, walnut: 1,
};

class Bag {
  m = new Map<MbMat, Acc>();
  get(k: MbMat) { let a = this.m.get(k); if (!a) this.m.set(k, (a = { pos: [], nor: [], uv: [], idx: [] })); return a; }
  build() {
    const out: { key: MbMat; geo: THREE.BufferGeometry }[] = [];
    for (const [key, a] of this.m) {
      if (!a.idx.length) continue;
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.Float32BufferAttribute(a.pos, 3));
      g.setAttribute("normal", new THREE.Float32BufferAttribute(a.nor, 3));
      g.setAttribute("uv", new THREE.Float32BufferAttribute(a.uv, 2));
      g.setIndex(a.idx); g.computeBoundingSphere();
      out.push({ key, geo: g });
    }
    return out;
  }
}

const area = (P: PlanPoly) => { let s = 0; for (let i = 0; i < P.length; i++) { const a = P[i], b = P[(i + 1) % P.length]; s += a[0] * b[1] - b[0] * a[1]; } return s / 2; };
/** drop repeated and collinear points (the drawing's polygons carry many) */
function clean(P: PlanPoly): PlanPoly {
  const out: PlanPoly = [];
  for (const q of P) if (!out.length || Math.hypot(q[0] - out[out.length - 1][0], q[1] - out[out.length - 1][1]) > 0.004) out.push(q);
  if (out.length > 2 && Math.hypot(out[0][0] - out[out.length - 1][0], out[0][1] - out[out.length - 1][1]) < 0.004) out.pop();
  for (let i = 0; i < out.length && out.length > 3; ) {
    const a = out[(i + out.length - 1) % out.length], b = out[i], c = out[(i + 1) % out.length];
    const cr = (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0]);
    if (Math.abs(cr) < 1e-5) out.splice(i, 1); else i++;
  }
  return out;
}

/** vertical walls of a polygon prism y0 → y1, normals outward (x/z plan frame: x right, z down); texture v from `base` */
function sides(b: Bag, k: MbMat, P: PlanPoly, y0: number, y1: number, base = 0) {
  const a = b.get(k), t = TILE[k], ccw = area(P) > 0; // area > 0: clockwise on screen (z down) → outward = left of a→b
  let u = 0;
  for (let i = 0; i < P.length; i++) {
    const p = P[i], q = P[(i + 1) % P.length], L = Math.hypot(q[0] - p[0], q[1] - p[1]);
    if (L < 1e-4) continue;
    let nx = (q[1] - p[1]) / L, nz = -(q[0] - p[0]) / L;
    if (!ccw) { nx = -nx; nz = -nz; }
    const o = a.pos.length / 3;
    a.pos.push(p[0], y0, p[1], q[0], y0, q[1], q[0], y1, q[1], p[0], y1, p[1]);
    for (let j = 0; j < 4; j++) a.nor.push(nx, 0, nz);
    const v0 = (y0 - base) / t, v1 = (y1 - base) / t;
    a.uv.push(u / t, v0, (u + L) / t, v0, (u + L) / t, v1, u / t, v1);
    u += L;
    // front face where the normal points: (q − p) × up gives (dz, −dx)… pick the winding that faces (nx, nz)
    const fx = (q[1] - p[1]), fz = -(q[0] - p[0]);
    if (fx * nx + fz * nz > 0) a.idx.push(o, o + 2, o + 1, o, o + 3, o + 2); else a.idx.push(o, o + 1, o + 2, o, o + 2, o + 3);
  }
}
/** horizontal cap of a polygon (with optional holes) at y, facing up or down */
function cap(b: Bag, k: MbMat, P: PlanPoly, y: number, up: boolean, holes: PlanPoly[] = []) {
  const a = b.get(k), t = TILE[k];
  const tris = THREE.ShapeUtils.triangulateShape(P.map((q) => new THREE.Vector2(q[0], q[1])), holes.map((h) => h.map((q) => new THREE.Vector2(q[0], q[1]))));
  const all = [...P, ...holes.flat()];
  const o = a.pos.length / 3;
  for (const q of all) { a.pos.push(q[0], y, q[1]); a.nor.push(0, up ? 1 : -1, 0); a.uv.push(q[0] / t, q[1] / t); }
  for (const [i, j, l] of tris) {
    const A = all[i], B = all[j], C = all[l];
    // y-up normal of (A, B, C) in x/z: (B − A) × (C − A) · ŷ = (Bz − Az)(Cx − Ax) − (Bx − Ax)(Cz − Az)
    const ny = (B[1] - A[1]) * (C[0] - A[0]) - (B[0] - A[0]) * (C[1] - A[1]);
    if ((ny > 0) === up) a.idx.push(o + i, o + j, o + l); else a.idx.push(o + i, o + l, o + j);
  }
}
function prism(b: Bag, k: MbMat, P0: PlanPoly, y0: number, y1: number, top = true, bottom = false, base = 0) {
  const P = clean(P0);
  if (P.length < 3 || Math.abs(area(P)) < 1e-4) return;
  sides(b, k, P, y0, y1, base);
  if (top) cap(b, k, P, y1, true);
  if (bottom) cap(b, k, P, y0, false);
}

// ---------------------------------------------------------------- 1st-floor terrace
// The architect's electrical plans (« PLAN ELEC », 20/10/2024) furnish the outer ring of the 1st floor with outdoor round
// tables, lounge chairs and plants, outside the windowed wall of the offices: a TERRACE on the ground floor's roof. Its outer
// wall is a parapet (height 1.10 m, provisional) and it has no ceiling. The offices' own outline is the 2nd floor's slab.
const S2 = () => MIBTECH_PLANS[2].slab[0];
const centroid = (P: PlanPoly): [number, number] => [P.reduce((s, q) => s + q[0], 0) / P.length, P.reduce((s, q) => s + q[1], 0) / P.length];
/** a 1st-floor element of the terrace (outside the offices' outline) */
export const onTerrace = (f: MbFloor, P: PlanPoly) => f === 1 && !inOutline(S2(), ...centroid(P));
export const MB_PARAPET = 1.1;

/** One office floor: structure, envelope, partitions, joinery, slab and ceiling, furniture (stair flights: see the stair builder). */
function floorParts(f: MbFloor, plan: FloorPlan) {
  const b = new Bag(), y = floorY(f), top = y + MB_H.floor - MB_H.slab;
  for (const P of plan.masonry) prism(b, "wall", P, y, onTerrace(f, P) ? y + MB_PARAPET : top, true, false, y);
  for (const P of plan.concrete) prism(b, "column", P, y, top, true, false, y);
  for (const P of plan.window) {
    if (onTerrace(f, P)) {              // terrace: glass balustrade on a low kerb
      prism(b, "wall", P, y, y + 0.1);
      prism(b, "glass", pane(P, 0.02), y + 0.1, y + MB_PARAPET - 0.05, false);
      prism(b, "frame", pane(P, 0.06), y + MB_PARAPET - 0.05, y + MB_PARAPET);
      continue;
    }
    prism(b, "wall", P, y, y + MB_H.sill, true, false, y); // sill, glass, lintel
    prism(b, "glass", pane(P, 0.03), y + MB_H.sill, y + MB_H.head, false);
    prism(b, "frame", P, y + MB_H.head, y + MB_H.head + 0.06);
    prism(b, "wall", P, y + MB_H.head + 0.06, top, true, false, y);
  }
  for (const P of plan.curtain) {       // glazed walls: the street front (dressed by the façade from the photos), and inside the
    const inside = centroid(P)[1] < -1; // glazed partitions of rooms and offices, with the frosted film of the photos
    prism(b, inside ? "frost" : "glass", P, y + 0.05, y + MB_H.ceiling - 0.05, false, false, y);
    prism(b, "frame", P, y, y + 0.05);
    prism(b, "frame", P, y + MB_H.ceiling - 0.05, y + MB_H.ceiling);
  }
  // glazed partitions: frosted glass in black frames (office photos)
  for (const P of plan.glass) {
    prism(b, "frost", P, y + 0.05, y + MB_H.ceiling - 0.05, false, false, y);
    prism(b, "frame", P, y, y + 0.05);
    prism(b, "frame", P, y + MB_H.ceiling - 0.05, y + MB_H.ceiling);
  }
  for (const P of plan.partition) prism(b, "partition", P, y, y + MB_H.ceiling, true, false, y);
  for (const P of plan.cubicle) prism(b, "cubicle", P, y + 0.15, y + MB_H.cubicle);
  for (const P of plan.door) prism(b, "door", P, y, y + MB_H.door);
  for (const P of plan.lift) prism(b, "lift", P, y, top);
  const S = clean(plan.slab[0]), inner = f === 1 ? clean(S2()) : S;
  // the stair well: open in this floor (the flights coming up from below) and in its ceiling (the flights going up), not above floor 3
  const well = [STAIR.well];
  if (f === 1) cap(b, "terrace", S, y + 0.004, true, well);  // terrace tiles, under the offices' floor
  cap(b, "floor", inner, y + 0.03, true, well);
  cap(b, "ceiling", inner, y + MB_H.ceiling, false, f < 3 ? well : []);
  sides(b, "slabEdge", S, y - MB_H.slab, y);                  // slab edge, seen between the floors
  cap(b, "ceiling", S, y - MB_H.slab, false, well);            // soffit of this floor's slab
  // top floor: the well has no flight going up — guard rail over the drop of the flight coming up (south half, floor side)
  if (f === 3) sides(b, "rail", [[STAIR.x1 + 0.02, STAIR.zMid + 0.05], [STAIR.x1 + 0.02, STAIR.z1], [STAIR.x1 + 0.02, STAIR.z1]], y, y + 1.0);
  furniture(b, y, MIBTECH_FURNITURE[f]);
  carpet(b, f, plan, y);
  return b.build();
}

// ---------------------------------------------------------------- furniture (architect's electrical plans, 20/10/2024)
// Footprints and positions as drawn (mibtechFurnitureData.ts, generated); heights and shapes are standard office furniture
// (desk 0.75 m, seat 0.46 m…), simplified. Finishes after the office photos: beige desk tops, black mesh chairs.
/** box of footprint L × T (plan frame) centred on (x, z), long side at angle a, from y0 to y1 */
function box(b: Bag, k: MbMat, x: number, z: number, L: number, T: number, a: number, y0: number, y1: number) {
  const ux = Math.cos(a) * L / 2, uz = Math.sin(a) * L / 2, vx = -Math.sin(a) * T / 2, vz = Math.cos(a) * T / 2;
  prism(b, k, [[x - ux - vx, z - uz - vz], [x + ux - vx, z + uz - vz], [x + ux + vx, z + uz + vz], [x - ux + vx, z - uz + vz]], y0, y1, true, false);
}
/** n-gon prism of radius r */
function disc(b: Bag, k: MbMat, x: number, z: number, r: number, y0: number, y1: number, n = 10) {
  const P: PlanPoly = [];
  for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; P.push([x + Math.cos(t) * r, z + Math.sin(t) * r]); }
  prism(b, k, P, y0, y1, true, false);
}
const K = (n: (typeof FURN_KINDS)[number]) => FURN_KINDS.indexOf(n);
function furniture(b: Bag, y: number, items: FurnItem[]) {
  for (const [k, x, z, L, T, a] of items) {
    const ca = Math.cos(a), sa = Math.sin(a);
    const at = (u: number, v: number): [number, number] => [x + ca * u - sa * v, z + sa * u + ca * v]; // local (u along a, v across)
    switch (k) {
      case K("desk"): {            // workstation: top + two panel legs
        box(b, "desk", x, z, L, T, a, y + 0.72, y + 0.75);
        for (const e of [-1, 1]) { const [px, pz] = at(e * (L / 2 - 0.03), 0); box(b, "metal", px, pz, 0.03, T - 0.1, a, y, y + 0.72); }
        { const [px, pz] = at(L / 2 - 0.3, 0); box(b, "chair", px, pz, 0.42, 0.5, a, y + 0.03, y + 0.6); } // drawer unit (photos)
        break;
      }
      case K("table"): {           // meeting / office table: top + four legs
        box(b, "desk", x, z, L, T, a, y + 0.72, y + 0.75);
        for (const [eu, ev] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) { const [px, pz] = at(eu * (L / 2 - 0.08), ev * (T / 2 - 0.08)); box(b, "metal", px, pz, 0.05, 0.05, a, y, y + 0.72); }
        break;
      }
      case K("screen"):            // desk divider, on the desk tops
        box(b, "panel", x, z, L, Math.max(T, 0.025), a, y + 0.75, y + 1.12);
        break;
      case K("monitor"): {
        box(b, "screen", x, z, L * 0.9, 0.025, a, y + 0.92, y + 1.2);
        box(b, "metal", x, z, 0.05, 0.05, a, y + 0.75, y + 0.92);
        break;
      }
      case K("chair"): {           // office chair, black mesh (a = the direction it faces)
        const [bx, bz] = at(-0.23, 0);
        box(b, "chair", x, z, 0.46, 0.48, a, y + 0.42, y + 0.49);
        box(b, "chair", bx, bz, 0.05, 0.46, a, y + 0.52, y + 1.02);
        box(b, "metal", x, z, 0.05, 0.05, a, y + 0.08, y + 0.42);
        box(b, "metal", x, z, 0.56, 0.04, a, y + 0.03, y + 0.08);
        box(b, "metal", x, z, 0.04, 0.56, a, y + 0.03, y + 0.08);
        break;
      }
      case K("round"):             // terrace table
        disc(b, "metal", x, z, Math.min(L, T) / 2, y + 0.7, y + 0.73, 16);
        disc(b, "metal", x, z, 0.04, y, y + 0.7, 6);
        break;
      case K("lounge"):            // terrace lounge chair
        box(b, "fabric", x, z, L * 0.9, T * 0.9, a, y + 0.05, y + 0.4);
        break;
      case K("armchair"): case K("sofa"): {
        box(b, "fabric", x, z, L, T, a, y + 0.05, y + 0.42);
        for (const e of [-1, 1]) { const [px, pz] = at(e * (L / 2 - 0.08), 0); box(b, "fabric", px, pz, 0.16, T, a, y + 0.42, y + 0.62); }
        break;
      }
      case K("cabinet"):           // storage units; counters (kitchenette, vanity): white gloss with a walnut worktop (photos)
        if (L >= 1.5 && T <= 0.75) { box(b, "cabinet", x, z, L, T, a, y + 0.08, y + 0.86); box(b, "walnut", x, z, L + 0.02, T + 0.02, a, y + 0.86, y + 0.9); }
        else box(b, "cabinet", x, z, L, T, a, y, y + 0.85);
        break;
      case K("low"):               // low tables, shower trays
        box(b, "cabinet", x, z, L, T, a, y, y + 0.4);
        break;
      case K("plant"): {
        const r = Math.min(L, T) / 2;
        disc(b, "pot", x, z, 0.2, y, y + 0.45);
        disc(b, "leaf", x, z, r * 0.7, y + 0.45, y + 0.85);
        disc(b, "leaf", x, z, r * 0.85, y + 0.85, y + 1.2);
        disc(b, "leaf", x, z, r * 0.5, y + 1.2, y + 1.5);
        break;
      }
      case K("wc"):
        box(b, "porcelain", x, z, L * 0.9, T * 0.85, a, y, y + 0.4);
        break;
      case K("rug"):
        box(b, "fabric", x, z, L, T, a, y + 0.03, y + 0.045);
        break;
    }
  }
}

// ---------------------------------------------------------------- carpet in the closed meeting rooms (photos)
// The room of each table drawn with ≥ 4 chairs around it: flood fill on a 10 cm grid of the floor, the walls, partitions,
// glazed walls, cubicles and cores as barriers, doorways closed by a 0.5 m dilation; a room larger than 45 m² is open space
// (no carpet). The carpet then grows back to the walls.
function carpet(b: Bag, f: MbFloor, plan: FloorPlan, y: number) {
  const R = 0.1, S = plan.slab[0], xs = S.map((q) => q[0]), zs = S.map((q) => q[1]);
  const X0 = Math.min(...xs), Z0 = Math.min(...zs), NX = Math.ceil((Math.max(...xs) - X0) / R) + 1, NZ = Math.ceil((Math.max(...zs) - Z0) / R) + 1;
  const wall = new Uint8Array(NX * NZ);
  for (const P of [...plan.masonry, ...plan.concrete, ...plan.partition, ...plan.glass, ...plan.cubicle, ...plan.window, ...plan.curtain, ...plan.lift, ...plan.stair]) {
    const px = P.map((q) => q[0]), pz = P.map((q) => q[1]);
    const i0 = Math.max(0, Math.floor((Math.min(...px) - X0) / R) - 1), i1 = Math.min(NX - 1, Math.ceil((Math.max(...px) - X0) / R) + 1);
    const j0 = Math.max(0, Math.floor((Math.min(...pz) - Z0) / R) - 1), j1 = Math.min(NZ - 1, Math.ceil((Math.max(...pz) - Z0) / R) + 1);
    for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) {
      const cx = X0 + i * R, cz = Z0 + j * R;
      if (inOutline(P, cx, cz) || (i1 - i0 <= 2 || j1 - j0 <= 2)) wall[j * NX + i] = 1; // thin elements: their whole bounding cells
    }
  }
  for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++) if (!inOutline(S, X0 + i * R, Z0 + j * R)) wall[j * NX + i] = 1;
  const D = 5, closed = new Uint8Array(NX * NZ);
  for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++) if (wall[j * NX + i])
    for (let dj = -D; dj <= D; dj++) for (let di = -D; di <= D; di++) {
      const a = i + di, c = j + dj;
      if (a >= 0 && c >= 0 && a < NX && c < NZ && di * di + dj * dj <= D * D) closed[c * NX + a] = 1;
    }
  const carpetCells = new Uint8Array(NX * NZ), items = MIBTECH_FURNITURE[f];
  for (const t of items) {
    if (t[0] !== K("table")) continue;
    const chairs = items.filter((c) => c[0] === K("chair") && Math.hypot(c[1] - t[1], c[2] - t[2]) < Math.max(t[3], t[4]) / 2 + 1).length;
    if (chairs < 4) continue;
    const si = Math.round((t[1] - X0) / R), sj = Math.round((t[2] - Z0) / R);
    if (si < 0 || sj < 0 || si >= NX || sj >= NZ || closed[sj * NX + si]) continue;
    const seen = new Uint8Array(NX * NZ), st = [sj * NX + si], room: number[] = [];
    seen[st[0]] = 1;
    while (st.length && room.length < 4600) {
      const k = st.pop()!; room.push(k);
      const i = k % NX, j = (k - i) / NX;
      for (const n of [i > 0 ? k - 1 : -1, i < NX - 1 ? k + 1 : -1, j > 0 ? k - NX : -1, j < NZ - 1 ? k + NX : -1])
        if (n >= 0 && !seen[n] && !closed[n]) { seen[n] = 1; st.push(n); }
    }
    if (room.length >= 4600) continue;                         // open space: no carpet
    // grow back to the walls (the dilation's width), never through a wall
    let front = room;
    for (let g = 0; g < D + 1; g++) {
      const next: number[] = [];
      for (const k of front) {
        const i = k % NX, j = (k - i) / NX;
        for (const n of [i > 0 ? k - 1 : -1, i < NX - 1 ? k + 1 : -1, j > 0 ? k - NX : -1, j < NZ - 1 ? k + NX : -1])
          if (n >= 0 && !seen[n] && !wall[n]) { seen[n] = 1; next.push(n); }
      }
      room.push(...next); front = next;
    }
    for (const k of room) carpetCells[k] = 1;
    // wall display at one end of the table (photos: interactive screen in a white frame, soundbar below), on the end wall
    // farther from the table; skipped when no wall is found within 4 m
    const ux = Math.cos(t[5]), uz = Math.sin(t[5]);
    const reach = (sg: number) => {
      for (let d = Math.max(t[3], t[4]) / 2; d < 4; d += R / 2) {
        const i = Math.round((t[1] + ux * sg * d - X0) / R), j = Math.round((t[2] + uz * sg * d - Z0) / R);
        if (i < 0 || j < 0 || i >= NX || j >= NZ || wall[j * NX + i]) return d;
      }
      return Infinity;
    };
    const ends = [[1, reach(1)], [-1, reach(-1)]].filter((e) => e[1] < Infinity).sort((p, q) => q[1] - p[1]);
    if (ends.length) {
      const [sg, dw] = ends[0];
      const cx = t[1] + ux * sg * (dw - 0.1), cz = t[2] + uz * sg * (dw - 0.1), ang = t[5] + Math.PI / 2;
      box(b, "porcelain", cx, cz, 1.5, 0.05, ang, y + 1.08, y + 1.96);                                   // white frame
      box(b, "screen", cx - ux * sg * 0.03, cz - uz * sg * 0.03, 1.4, 0.02, ang, y + 1.16, y + 1.92);    // the screen, in front
      box(b, "chair", cx - ux * sg * 0.02, cz - uz * sg * 0.02, 0.9, 0.08, ang, y + 0.94, y + 1.02);     // soundbar
    }
  }
  // one quad per run of carpet cells in each row
  for (let j = 0; j < NZ; j++) {
    let i = 0;
    while (i < NX) {
      if (!carpetCells[j * NX + i]) { i++; continue; }
      const i0 = i;
      while (i < NX && carpetCells[j * NX + i]) i++;
      const x0 = X0 + (i0 - 0.5) * R, x1 = X0 + (i - 0.5) * R, z0 = Z0 + (j - 0.5) * R, z1 = Z0 + (j + 0.5) * R;
      cap(b, "carpet", [[x0, z0], [x1, z0], [x1, z1], [x0, z1]], y + 0.036, true);
    }
  }
}

/** the glass of a window: a thin pane (thickness t) along the window's long axis, through its middle */
function pane(P: PlanPoly, t: number): PlanPoly {
  let best = 0, ux = 1, uz = 0;
  for (let i = 0; i < P.length; i++) {
    const a = P[i], c = P[(i + 1) % P.length], L = Math.hypot(c[0] - a[0], c[1] - a[1]);
    if (L > best) { best = L; ux = (c[0] - a[0]) / L; uz = (c[1] - a[1]) / L; }
  }
  const cx = P.reduce((s, q) => s + q[0], 0) / P.length, cz = P.reduce((s, q) => s + q[1], 0) / P.length;
  const us = P.map((q) => (q[0] - cx) * ux + (q[1] - cz) * uz), u0 = Math.min(...us), u1 = Math.max(...us);
  const vx = -uz * t / 2, vz = ux * t / 2;
  return [[cx + ux * u0 - vx, cz + uz * u0 - vz], [cx + ux * u1 - vx, cz + uz * u1 - vz], [cx + ux * u1 + vx, cz + uz * u1 + vz], [cx + ux * u0 + vx, cz + uz * u0 + vz]];
}

// ---------------------------------------------------------------- stair (the core drawn on the three plans)
// Switchback, as drawn: floor landing to the east (door side), two flights of 7 treads (≈ 0.29 m × 1.21 m) running west,
// half landing to the west. The flight and landing outlines are read from the plans (class "stair", floor 2).
// Riser height = floor-to-floor / 16 (8 risers a flight): 0.2375 m with the provisional 3.8 m — STEEPER than usual, the
// plans' stair being schematic at this stage (APS); an open question for the architect (docs: phase A).
const STAIR = (() => {
  const P = MIBTECH_PLANS[2].stair.map((Q) => { const xs = Q.map((q) => q[0]), zs = Q.map((q) => q[1]); return { x0: Math.min(...xs), x1: Math.max(...xs), z0: Math.min(...zs), z1: Math.max(...zs) }; });
  const treads = P.filter((r) => r.x1 - r.x0 < 0.4 && r.z1 - r.z0 > 1);
  const land = P.reduce((a, r) => ((r.x1 - r.x0) * (r.z1 - r.z0) > (a.x1 - a.x0) * (a.z1 - a.z0) ? r : a), P[0]);
  const zMid = (Math.min(...treads.map((r) => r.z0)) + Math.max(...treads.map((r) => r.z1))) / 2;
  const north = treads.filter((r) => (r.z0 + r.z1) / 2 < zMid).sort((a, b) => b.x0 - a.x0);   // rising back to the east
  const south = treads.filter((r) => (r.z0 + r.z1) / 2 >= zMid).sort((a, b) => b.x0 - a.x0); // rising to the west
  const x0 = land.x0, x1 = Math.max(...treads.map((r) => r.x1)), z0 = land.z0, z1 = land.z1;
  return { north, south, land, well: [[x0, z0], [x1, z0], [x1, z1], [x0, z1]] as PlanPoly, x1, zMid, z0, z1 };
})();
export const MB_STAIR = STAIR;
/** flights and landing between level y0 and y1 (ground → 1st, 1st → 2nd, 2nd → 3rd): solid steps */
function flights(b: Bag, y0: number, y1: number) {
  const n = STAIR.south.length + 1, rise = (y1 - y0) / (2 * n);
  STAIR.south.forEach((r, i) => prism(b, "stair", [[r.x0, r.z0], [r.x1, r.z0], [r.x1, r.z1], [r.x0, r.z1]], y0, y0 + (i + 1) * rise));
  const L = STAIR.land;
  prism(b, "stair", [[L.x0, L.z0], [L.x1, L.z0], [L.x1, L.z1], [L.x0, L.z1]], y0 + n * rise - 0.2, y0 + n * rise, true, true);
  [...STAIR.north].reverse().forEach((r, i) => prism(b, "stair", [[r.x0, r.z0], [r.x1, r.z0], [r.x1, r.z1], [r.x0, r.z1]], y0 + n * rise, y0 + (n + i + 1) * rise));
  // handrail between the flights (on the well's axis)
  prism(b, "rail", [[STAIR.land.x1, STAIR.zMid - 0.02], [STAIR.x1, STAIR.zMid - 0.02], [STAIR.x1, STAIR.zMid + 0.02], [STAIR.land.x1, STAIR.zMid + 0.02]], y0, y1 + 0.9);
}
/** the flights up to floor f (f = 1: from the ground floor) */
function stairParts(f: MbFloor) {
  const b = new Bag();
  flights(b, f === 1 ? 0 : floorY((f - 1) as MbFloor), floorY(f));
  return b.build();
}

/** Roof: the top of floor 3 (the 1st floor's ring is a terrace, open to the sky). */
function roofParts() {
  const b = new Bag();
  const S3 = clean(MIBTECH_PLANS[3].slab[0]);
  cap(b, "roof", S3, MB_TOP, true);
  sides(b, "slabEdge", S3, MB_TOP - MB_H.slab, MB_TOP + 0.6);    // roof slab and parapet
  return b.build();
}

// ---------------------------------------------------------------- ground floor: street front and office entrance hall
// No plan of the ground floor. Street front after the photos (MibtechBuilding front()): the floors overhang the pavement by
// MB_CANT; the office entrance is a portal recessed 2 m at the north-east end, with a glazed door. Behind it, a PROVISIONAL
// entrance hall (walls and finishes estimated) leads straight to the stair and the lift, whose cores are drawn on the plans.
export const MB_CANT = 1.4;
const SLAB1_X1 = Math.max(...MIBTECH_PLANS[1].slab[0].map((q) => q[0]));
export const MB_PORTAL = (() => {
  const zs = -MB_CANT, a = SLAB1_X1 - 7, b = SLAB1_X1 - 2;
  return { a, b, zs, zb: zs - 2, d0: a + 1.5, d1: a + 3.5, door: 4.0 };
})();
export const MB_HALL = (() => {
  const sb = MIBTECH_PLANS[1].stair_meta.box, lb = MIBTECH_PLANS[1].stair_meta.lift, P = MB_PORTAL;
  const hx0 = P.d0 - 0.05, hx1 = P.b, cx0 = sb[0][0], cz0 = sb[0][1], cz1 = sb[1][1], lx1 = lb[1][0], lz0 = lb[0][1], lz1 = lb[1][1];
  const H = MB_H.ground - MB_H.slab;
  /** walls [x0, z0, x1, z1] (both faces), from 0 to H */
  const walls: [number, number, number, number][] = [
    [hx1, P.zb, hx1, cz0], [hx1, cz0, cx0, cz0], [cx0, cz0, cx0, cz1], [cx0, cz1, hx0, cz1],   // east, north, stair core
    [hx0, cz1, hx0, lz0], [hx0, lz0, lx1, lz0], [lx1, lz1, hx0, lz1], [hx0, lz1, hx0, P.zb],     // west, lift vestibule
    [P.d1, P.zb - 0.02, hx1, P.zb - 0.02],                                                      // inner face of the portal
  ];
  /** walkable rectangles [x0, z0, x1, z1] at y = 0: hall, stair core, lift vestibule */
  const rooms: [number, number, number, number][] = [[hx0, cz0, hx1, P.zb], [cx0, cz0, hx0, cz1], [lx1, lz0, hx0, lz1]];
  return { walls, rooms, H, x0: hx0, x1: hx1, z0: cz0, z1: P.zb };
})();

/** Ground floor: the floor-1 footprint as a closed plinth up to the first floor (the street front is dressed separately from
 *  the photos: shops, office entrance), and the provisional entrance hall. */
function groundParts() {
  const b = new Bag(), S1 = clean(MIBTECH_PLANS[1].slab[0]);
  // every edge but the street front (z ≈ 0): there the ground floor is set back under the floors (MibtechBuilding front())
  for (let i = 0; i < S1.length; i++) {
    const p = S1[i], q = S1[(i + 1) % S1.length];
    if (p[1] > -1.5 && q[1] > -1.5) continue;
    sides(b, "groundWall", [p, q, q], 0, MB_H.ground - MB_H.slab); // degenerate [p, q, q]: the wall p → q, both faces
  }
  const H = MB_HALL;
  for (const [x0, z0, x1, z1] of H.walls) sides(b, "wall", [[x0, z0], [x1, z1], [x1, z1]], 0, H.H);
  sides(b, "wall", [[MB_PORTAL.d0, MB_PORTAL.zb - 0.02], [MB_PORTAL.d1, MB_PORTAL.zb - 0.02], [MB_PORTAL.d1, MB_PORTAL.zb - 0.02]], MB_PORTAL.door, H.H);
  for (const [x0, z0, x1, z1] of H.rooms) cap(b, "floor", [[x0, z0], [x1, z0], [x1, z1], [x0, z1]], 0.012, true);
  for (const P of MIBTECH_PLANS[1].lift) prism(b, "lift", P, 0, H.H);
  return b.build();
}

export type MbParts = { key: MbMat; geo: THREE.BufferGeometry }[];
/** every part of the building, keyed by group: "f1" … "f3" (each floor), "s1" … "s3" (the flights up to it), "roof", "ground" */
export function buildMibtech(): Record<string, MbParts> {
  const out: Record<string, MbParts> = { roof: roofParts(), ground: groundParts() };
  for (const f of MB_FLOORS) { out[`f${f}`] = floorParts(f, MIBTECH_PLANS[f]); out[`s${f}`] = stairParts(f); }
  return out;
}
/** the floor-1 outline (largest), building frame — for the city layer's skip test and the walk solids */
export const MB_OUTLINE: PlanPoly = clean(MIBTECH_PLANS[1].slab[0]);
export function inOutline(P: PlanPoly, x: number, z: number) {
  let c = false;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    if ((P[i][1] > z) !== (P[j][1] > z) && x < ((P[j][0] - P[i][0]) * (z - P[i][1])) / (P[j][1] - P[i][1]) + P[i][0]) c = !c;
  }
  return c;
}
